from __future__ import annotations

import json
import math
import os
import shutil
import subprocess
import sys
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
OUTPUT_DIR = TASK_DIR / "outputs"
REPORT_PATH = OUTPUT_DIR / "public_reproduction_report.json"


CPP_PROBE = r"""
#include "tabulate.h"

#include <cmath>
#include <functional>
#include <iomanip>
#include <iostream>
#include <limits>
#include <string>
#include <vector>

namespace {

constexpr int kLastLayerSize = 3;
constexpr double kLower = -1.0;
constexpr double kUpper = 1.0;
constexpr double kMax = 2.8;
constexpr double kStride0 = 0.5;
constexpr double kStride1 = 0.6;
constexpr double kStep = 1.0e-6;

std::vector<double> make_table() {
  const int segment_count = 10;
  std::vector<double> table(segment_count * kLastLayerSize * 6);
  for (int segment = 0; segment < segment_count; ++segment) {
    for (int layer = 0; layer < kLastLayerSize; ++layer) {
      const int base = segment * kLastLayerSize * 6 + layer * 6;
      const double sign = (segment % 2 == 0) ? 1.0 : -1.0;
      table[base + 0] = 0.42 + 0.31 * segment - 0.07 * layer;
      table[base + 1] = sign * (0.83 + 0.11 * layer) + 0.03 * segment;
      table[base + 2] = -0.09 + 0.025 * segment + 0.015 * layer;
      table[base + 3] = 0.035 * (layer + 1) - 0.012 * segment;
      table[base + 4] = -0.006 * (segment + 1) + 0.002 * layer;
      table[base + 5] = 0.0015 * (segment % 3 - 1) + 0.0007 * (layer + 1);
    }
  }
  return table;
}

const std::vector<double> kTableInfo = {
    kLower, kUpper, kMax, kStride0, kStride1, -1.0};
const std::vector<double> kWeights = {0.72, -0.41, 0.23};
const std::vector<double> kEnv = {1.0, -0.24, 0.37, -0.18};
const std::vector<double> kAdjoint = {
    0.53, -0.17, 0.29,
    -0.31, 0.19, -0.11,
    0.23, -0.07, 0.13,
    -0.05, 0.09, -0.21};

double dot(const std::vector<double>& left, const std::vector<double>& right) {
  double value = 0.0;
  for (std::size_t ii = 0; ii < left.size(); ++ii) {
    value += left[ii] * right[ii];
  }
  return value;
}

double radial_value(const std::vector<double>& table, const double x) {
  std::vector<double> out(kLastLayerSize);
  const std::vector<double> em = {x};
  deepmd::tabulate_fusion_se_r_cpu<double>(
      out.data(), table.data(), kTableInfo.data(), em.data(), 1, 1,
      kLastLayerSize);
  return dot(out, kWeights);
}

double radial_sensitivity(const std::vector<double>& table, const double x) {
  std::vector<double> dy_dem(1);
  const std::vector<double> em = {x};
  deepmd::tabulate_fusion_se_r_grad_cpu<double>(
      dy_dem.data(), table.data(), kTableInfo.data(), em.data(),
      kWeights.data(), 1, 1, kLastLayerSize);
  return dy_dem[0];
}

double angular_value(const std::vector<double>& table, const double x) {
  std::vector<double> out(4 * kLastLayerSize);
  const std::vector<double> em_x = {x};
  deepmd::tabulate_fusion_se_a_cpu<double>(
      out.data(), table.data(), kTableInfo.data(), em_x.data(), kEnv.data(),
      nullptr, 1, 1, kLastLayerSize, false);
  return dot(out, kAdjoint);
}

double angular_sensitivity(const std::vector<double>& table, const double x) {
  std::vector<double> dy_dem_x(1);
  std::vector<double> dy_dem(4);
  std::vector<double> dy_dtwo(1);
  const std::vector<double> em_x = {x};
  deepmd::tabulate_fusion_se_a_grad_cpu<double>(
      dy_dem_x.data(), dy_dem.data(), dy_dtwo.data(), table.data(),
      kTableInfo.data(), em_x.data(), kEnv.data(), nullptr, kAdjoint.data(), 1,
      1, kLastLayerSize, false);
  return dy_dem_x[0];
}

double central_difference(const std::function<double(double)>& fn,
                          const double x) {
  return (fn(x + kStep) - fn(x - kStep)) / (2.0 * kStep);
}

double increment_gap(const std::function<double(double)>& fn,
                     const double x) {
  const double left = (fn(x) - fn(x - kStep)) / kStep;
  const double right = (fn(x + kStep) - fn(x)) / kStep;
  return std::abs(left - right);
}

void probe_family(const std::string& family,
                  const std::function<double(double)>& value_fn,
                  const std::function<double(double)>& sensitivity_fn) {
  const std::vector<double> points = {
      kLower - 0.31, kLower - 0.17, kLower, kLower + 0.23, 0.15,
      kUpper + 0.34, kMax - 0.09, kMax, kMax + 0.17, kMax + 0.31};

  double value_min = std::numeric_limits<double>::infinity();
  double value_max = -std::numeric_limits<double>::infinity();
  double max_sensitivity_gap = 0.0;
  double max_increment_gap = 0.0;
  for (const double x : points) {
    const double value = value_fn(x);
    const double sensitivity = sensitivity_fn(x);
    const double finite_difference = central_difference(value_fn, x);
    value_min = std::min(value_min, value);
    value_max = std::max(value_max, value);
    max_sensitivity_gap =
        std::max(max_sensitivity_gap, std::abs(sensitivity - finite_difference));
    max_increment_gap = std::max(max_increment_gap, increment_gap(value_fn, x));
  }
  std::cout << "SUMMARY " << family << " " << points.size() << " "
            << std::setprecision(17) << value_min << " " << value_max << " "
            << max_sensitivity_gap << " " << max_increment_gap << "\n";
}

}  // namespace

int main() {
  const std::vector<double> table = make_table();
  probe_family("radial", [&](double x) { return radial_value(table, x); },
               [&](double x) { return radial_sensitivity(table, x); });
  probe_family("angular", [&](double x) { return angular_value(table, x); },
               [&](double x) { return angular_sensitivity(table, x); });
  return 0;
}
"""


def _compiler() -> str | None:
    candidates = []
    env_cxx = os.environ.get("CXX")
    if env_cxx:
        candidates.append(env_cxx)
    candidates.extend(["c++", "g++", "clang++"])
    for candidate in candidates:
        resolved = shutil.which(candidate)
        if resolved:
            return resolved
    return None


def _runner_failure(reason: str, details: str = "") -> int:
    report = {
        "status": "runner_failure",
        "reason": reason,
        "details": details[-4000:],
    }
    OUTPUT_DIR.mkdir(exist_ok=True)
    REPORT_PATH.write_text(json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    print(json.dumps(report, indent=2, sort_keys=True))
    return 2


def _parse_summaries(stdout: str) -> list[dict[str, float | int | str]]:
    summaries: list[dict[str, float | int | str]] = []
    for line in stdout.splitlines():
        parts = line.strip().split()
        if len(parts) != 7 or parts[0] != "SUMMARY":
            continue
        family = parts[1]
        sample_count = int(parts[2])
        value_min, value_max, sensitivity_gap, increment_gap = map(float, parts[3:])
        summaries.append(
            {
                "family": family,
                "sample_count": sample_count,
                "value_min": value_min,
                "value_max": value_max,
                "max_abs_sensitivity_gap": sensitivity_gap,
                "max_local_increment_gap": increment_gap,
            }
        )
    return summaries


def main() -> int:
    OUTPUT_DIR.mkdir(exist_ok=True)
    compiler = _compiler()
    if compiler is None:
        return _runner_failure("cxx_compiler_not_found")

    probe_path = OUTPUT_DIR / "public_compressed_table_probe.cpp"
    binary_path = OUTPUT_DIR / ("public_compressed_table_probe.exe" if os.name == "nt" else "public_compressed_table_probe")
    probe_path.write_text(CPP_PROBE, encoding="utf-8")

    compile_cmd = [
        compiler,
        "-std=c++17",
        "-O2",
        "-I",
        str(TASK_DIR / "source" / "lib" / "include"),
        str(TASK_DIR / "source" / "lib" / "src" / "tabulate.cc"),
        str(probe_path),
        "-o",
        str(binary_path),
    ]
    compiled = subprocess.run(
        compile_cmd,
        cwd=TASK_DIR,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        timeout=120,
        check=False,
    )
    if compiled.returncode != 0:
        return _runner_failure("compile_failed", compiled.stdout)

    completed = subprocess.run(
        [str(binary_path)],
        cwd=TASK_DIR,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        timeout=60,
        check=False,
    )
    if completed.returncode != 0:
        return _runner_failure("probe_failed", completed.stdout)

    summaries = _parse_summaries(completed.stdout)
    if not summaries:
        return _runner_failure("empty_scientific_observation", completed.stdout)

    numeric_values = [
        float(item[key])
        for item in summaries
        for key in (
            "value_min",
            "value_max",
            "max_abs_sensitivity_gap",
            "max_local_increment_gap",
        )
    ]
    if not all(math.isfinite(value) for value in numeric_values):
        return _runner_failure("non_finite_scientific_observation", completed.stdout)

    max_sensitivity_gap = max(float(item["max_abs_sensitivity_gap"]) for item in summaries)
    max_increment_gap = max(float(item["max_local_increment_gap"]) for item in summaries)
    family_summaries: dict[str, dict[str, float | int]] = {}
    for item in summaries:
        family = str(item["family"])
        family_summaries[family] = {
            "sample_count": int(item["sample_count"]),
            "value_min": float(item["value_min"]),
            "value_max": float(item["value_max"]),
            "max_abs_sensitivity_gap": float(item["max_abs_sensitivity_gap"]),
            "max_local_increment_gap": float(item["max_local_increment_gap"]),
        }

    report = {
        "status": "workflow_completed",
        "observation": "compressed_table_response_consistency",
        "compiler": Path(compiler).name,
        "sample_count": sum(int(item["sample_count"]) for item in summaries),
        "max_abs_sensitivity_gap": max_sensitivity_gap,
        "max_local_increment_gap": max_increment_gap,
        "family_summaries": family_summaries,
    }
    REPORT_PATH.write_text(json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    print(json.dumps(report, indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

