398	  const FPTYPE _max = table_info[2];
399	  const FPTYPE stride0 = table_info[3];
400	  const FPTYPE stride1 = table_info[4];
401	// for every atom, execute a small manual gemm ~
402	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
403	#pragma omp parallel for
404	  for (int ii = 0; ii < nloc; ii++) {
405	    for (int jj = 0; jj < nnei_i; jj++) {
406	      // unloop not work as em_x is not sorted
407	      for (int kk = 0; kk < nnei_j; kk++) {
408	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
409	        FPTYPE ll = xx;
410	        int table_idx = 0;
411	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
412	                       table_idx);
413	        for (int mm = 0; mm < last_layer_size; mm++) {
414	          FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * mm + 0];
415	          FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * mm + 1];
416	          FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * mm + 2];
417	          FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * mm + 3];
418	          FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * mm + 4];
419	          FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * mm + 5];
420	          FPTYPE var =
