592	template <typename FPTYPE>
593	void deepmd::tabulate_fusion_se_t_tebd_grad_cpu(FPTYPE* dy_dem_x,
594	                                                const FPTYPE* table,
595	                                                const FPTYPE* table_info,
596	                                                const FPTYPE* em_x,
597	                                                const FPTYPE* em,
598	                                                const FPTYPE* dy,
599	                                                const int nloc,
600	                                                const int nnei_i,
601	                                                const int nnei_j,
602	                                                const int last_layer_size) {
603	  memset(dy_dem_x, 0, sizeof(FPTYPE) * nloc * nnei_i * nnei_j);
604	  const FPTYPE lower = table_info[0];
605	  const FPTYPE upper = table_info[1];
606	  const FPTYPE _max = table_info[2];
607	  const FPTYPE stride0 = table_info[3];
608	  const FPTYPE stride1 = table_info[4];
609	
610	#pragma omp parallel for
611	  for (int ii = 0; ii < nloc; ii++) {
612	    for (int jj = 0; jj < nnei_i; jj++) {
613	      for (int kk = 0; kk < nnei_j; kk++) {
614	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
615	        int table_idx = 0;
616	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
617	                       table_idx);
618	
619	        FPTYPE grad_sum = 0.0;
620	        for (int mm = 0; mm < last_layer_size; mm++) {
621	          FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * mm + 1];
622	          FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * mm + 2];
623	          FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * mm + 3];
624	          FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * mm + 4];
625	          FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * mm + 5];
626	
627	          FPTYPE dres_dxx = a1 + 2.0 * a2 * xx + 3.0 * a3 * xx * xx +
628	                            4.0 * a4 * xx * xx * xx +
629	                            5.0 * a5 * xx * xx * xx * xx;
630	
631	          FPTYPE dy_val =
632	              dy[ii * nnei_i * nnei_j * last_layer_size +
633	                 jj * nnei_j * last_layer_size + kk * last_layer_size + mm];
634	          grad_sum += dy_val * dres_dxx;
635	        }
636	
637	        dy_dem_x[ii * nnei_i * nnei_j + jj * nnei_j + kk] = grad_sum;
638	      }
639	    }
640	  }
