template <typename FPTYPE>
inline bool locate_xx(const FPTYPE& lower,
                      const FPTYPE& upper,
                      const FPTYPE& max,
                      const FPTYPE& stride0,
                      const FPTYPE& stride1,
                      FPTYPE& xx,
                      int& table_idx) {
  bool in_domain = true;
  if (xx < lower) {
    table_idx = 0;
    xx = (FPTYPE)0.;
    in_domain = false;
  } else if (xx < upper) {
    table_idx = (int)((xx - lower) / stride0);
    xx -= (table_idx * stride0 + lower);
  } else if (xx < max) {
    int first_stride = int((upper - lower) / stride0);
    table_idx = first_stride + (int)((xx - upper) / stride1);
    xx -= ((table_idx - first_stride) * stride1 + upper);
  } else {
    int first_stride = int((upper - lower) / stride0);
    table_idx =
        first_stride + (int)((max - upper) / stride1) - 1;
    // Clamp to the right endpoint of the stored polynomial support.  Points
    // beyond `max` are no longer treated as the left endpoint of the last
    // interval; they share the response of `max`.
    FPTYPE start = upper + (table_idx - first_stride) * stride1;
    xx = max - start;
    in_domain = false;
  }
  return in_domain;
}

template <typename FPTYPE>
inline bool locate_xx_se_t(const FPTYPE& lower,
                           const FPTYPE& upper,
                           const FPTYPE& min,
                           const FPTYPE& max,
                           const FPTYPE& stride0,
                           const FPTYPE& stride1,
                           FPTYPE& xx,
                           int& table_idx) {
  bool in_domain = true;
  if (xx < min) {
    table_idx = 0;
    xx = (FPTYPE)0.;
    in_domain = false;
  } else if (xx < lower) {
    table_idx = (int)((xx - min) / stride1);
    xx -= (table_idx * stride1 + min);
  } else if (xx < upper) {
    int first_stride = int((lower - min) / stride1);
    table_idx = first_stride + (int)((xx - lower) / stride0);
    xx -= ((table_idx - first_stride) * stride0 + lower);
  } else if (xx < max) {
    int first_stride =
        int((lower - min) / stride1) + int((upper - lower) / stride0);
    table_idx = first_stride + (int)((xx - upper) / stride1);
    xx -= ((table_idx - first_stride) * stride1 + upper);
  } else {
    int first_stride =
        int((lower - min) / stride1) + int((upper - lower) / stride0);
    table_idx = first_stride + (int)((max - upper) / stride1) - 1;
    // Same right-endpoint clamp as `locate_xx`.
    FPTYPE start = upper + (table_idx - first_stride) * stride1;
    xx = max - start;
    in_domain = false;
  }
  return in_domain;
}

