python3 - <<'PY'
import math
LLS=3; lower=-1.0; upper=1.0; maxv=2.8; s0=0.5; s1=0.6
# build public table
seg=10; T=[]
for s in range(seg):
    for l in range(LLS):
        sign=1.0 if s%2==0 else -1.0
        T.append([0.42+0.31*s-0.07*l, sign*(0.83+0.11*l)+0.03*s, -0.09+0.025*s+0.015*l, 0.035*(l+1)-0.012*s, -0.006*(s+1)+0.002*l, 0.0015*(s%3-1)+0.0007*(l+1)])
w=[0.72,-0.41,0.23]
def locate(x):
    if x<lower: return 0,0.0
    if x<upper:
        idx=int((x-lower)/s0); xx=x-(idx*s0+lower); return idx,xx
    if x<maxv:
        first=int((upper-lower)/s0); idx=first+int((x-upper)/s1); xx=x-((idx-first)*s1+upper); return idx,xx
    first=int((upper-lower)/s0); idx=first+int((maxv-upper)/s1)-1; start=upper+(idx-first)*s1; return idx,maxv-start
def poly(idx,xx,l):
    a=T[idx*LLS+l]
    return a[0]+(a[1]+(a[2]+(a[3]+(a[4]+a[5]*xx)*xx)*xx)*xx)*xx
def dpoly(idx,xx,l):
    a=T[idx*LLS+l]
    return a[1]+(2*a[2]+(3*a[3]+(4*a[4]+5*a[5]*xx)*xx)*xx)*xx
def v_lin(x):
    idx,xx=locate(x)
    if x<lower:
        # p(lower)+p'(lower)*(x-lower)
        return sum(w[l]*(poly(0,0.0,l)+dpoly(0,0.0,l)*(x-lower)) for l in range(LLS))
    if x>=maxv:
        idx,xx=locate(maxv)
        return sum(w[l]*(poly(idx,xx,l)+dpoly(idx,xx,l)*(x-maxv)) for l in range(LLS))
    return sum(w[l]*poly(idx,xx,l) for l in range(LLS))
def s_lin(x):
    if x<lower:
        return sum(w[l]*dpoly(0,0.0,l) for l in range(LLS))
    if x>=maxv:
        idx,xx=locate(maxv)
        return sum(w[l]*dpoly(idx,xx,l) for l in range(LLS))
    idx,xx=locate(x)
    return sum(w[l]*dpoly(idx,xx,l) for l in range(LLS))
pts=[lower-0.31,lower-0.17,lower,lower+0.23,0.15,upper+0.34,maxv-0.09,maxv,maxv+0.17,maxv+0.31]
h=1e-6
maxg=0; maxi=0
for x in pts:
    fd=(v_lin(x+h)-v_lin(x-h))/(2*h)
    gap=abs(s_lin(x)-fd)
    inc=abs((v_lin(x)-v_lin(x-h))/h-(v_lin(x+h)-v_lin(x))/h)
    maxg=max(maxg,gap); maxi=max(maxi,inc)
    print(x, v_lin(x), s_lin(x), fd, gap, inc)
print('maxg',maxg,'maxi',maxi)
