template <typename FPTYPE>
inline int table_segment_count(const FPTYPE& length, const FPTYPE& stride) {
  // Valid compressed tables use integral segment counts.  Rounding avoids
  // missing the last interval when `length / stride` is just below an integer
  // in floating-point arithmetic (e.g. 1.2 / 0.4 == 2.9999999999999996).
  return (int)(length / stride + (FPTYPE)0.5);
}

template <typename FPTYPE>
inline bool locate_xx(const FPTYPE& lower,
                      const FPTYPE& upper,
                      const FPTYPE& max,
                      const FPTYPE& stride0,
                      const FPTYPE& stride1,
                      FPTYPE& xx,
                      int& table_idx) {
  const int first_count = table_segment_count(upper - lower, stride0);
  const int second_count = table_segment_count(max - upper, stride1);
  bool in_domain = true;
  if (xx < lower) {
    table_idx = 0;
    xx = (FPTYPE)0.;
    in_domain = false;
  } else if (xx < upper) {
    int idx = (int)((xx - lower) / stride0);
    if (idx < 0) {
      idx = 0;
    }
    if (idx >= first_count) {
      idx = first_count - 1;
    }
    table_idx = idx;
    xx -= (idx * stride0 + lower);
  } else if (xx < max) {
    if (second_count > 0) {
      int idx = (int)((xx - upper) / stride1);
      if (idx < 0) {
        idx = 0;
      }
      if (idx >= second_count) {
        idx = second_count - 1;
      }
      table_idx = first_count + idx;
      xx -= (idx * stride1 + upper);
    } else {
      // No extended table: clamp to the right end of the central table.
      table_idx = first_count - 1;
      xx = upper - (lower + table_idx * stride0);
    }
  } else {
    if (second_count > 0) {
      table_idx = first_count + second_count - 1;
      FPTYPE start = upper + (second_count - 1) * stride1;
      xx = max - start;
    } else {
      table_idx = first_count - 1;
      FPTYPE start = lower + table_idx * stride0;
      xx = max - start;
    }
    in_domain = false;
  }
  return in_domain;
}

template <typename FPTYPE>
inline bool locate_xx_se_t(const FPTYPE& lower,
                           const FPTYPE& upper,
                           const FPTYPE& min,
                           const FPTYPE& max,
                           const FPTYPE& stride0,
                           const FPTYPE& stride1,
                           FPTYPE& xx,
                           int& table_idx) {
  const int left_count = table_segment_count(lower - min, stride1);
  const int middle_count = table_segment_count(upper - lower, stride0);
  const int right_count = table_segment_count(max - upper, stride1);
  const int first_stride = left_count + middle_count;
  bool in_domain = true;
  if (xx < min) {
    table_idx = 0;
    xx = (FPTYPE)0.;
    in_domain = false;
  } else if (xx < lower) {
    int idx = (int)((xx - min) / stride1);
    if (idx < 0) {
      idx = 0;
    }
    if (idx >= left_count) {
      idx = left_count - 1;
    }
    table_idx = idx;
    xx -= (idx * stride1 + min);
  } else if (xx < upper) {
    int idx = (int)((xx - lower) / stride0);
    if (idx < 0) {
      idx = 0;
    }
    if (idx >= middle_count) {
      idx = middle_count - 1;
    }
    table_idx = left_count + idx;
    xx -= (idx * stride0 + lower);
  } else if (xx < max) {
    if (right_count > 0) {
      int idx = (int)((xx - upper) / stride1);
      if (idx < 0) {
        idx = 0;
      }
      if (idx >= right_count) {
        idx = right_count - 1;
      }
      table_idx = first_stride + idx;
      xx -= (idx * stride1 + upper);
    } else {
      table_idx = first_stride - 1;
      xx = upper - (lower + (table_idx - left_count) * stride0);
    }
  } else {
    if (right_count > 0) {
      table_idx = first_stride + right_count - 1;
      FPTYPE start = upper + (right_count - 1) * stride1;
      xx = max - start;
    } else if (middle_count > 0) {
      table_idx = left_count + middle_count - 1;
      FPTYPE start = lower + (middle_count - 1) * stride0;
      xx = max - start;
    } else {
      table_idx = 0;
      xx = (FPTYPE)0.;
    }
    in_domain = false;
  }
  return in_domain;
}

